def profile_addresses_to_book(apps, schema_editor):
    CustomerProfile = apps.get_model("store", "CustomerProfile")
    Address = apps.get_model("store", "Address")
    for p in CustomerProfile.objects.select_related("user").exclude(address_line1="").iterator():
        if not (p.city and p.pincode):
            continue
        u = p.user
        Address.objects.create(
            user=u, label="Home", name=(f"{u.first_name} {u.last_name}".strip() or u.username)[:160],
            phone=(p.phone or "")[:20], address_line1=p.address_line1, address_line2=p.address_line2 or "",
            city=p.city, state=p.state or "", pincode=p.pincode, country=p.country or "India",
            location_url=p.location_url or "", is_default=True,
        )


